"""
bulwarkos_wifi.cli — command-line interface for BulwarkOS WiFi management.

Usage:
    python3 -m bulwarkos_wifi.cli <command> [args]
    bulwark-wifi <command> [args]          # via entry point

Commands:
    status                     Show connection status and proxy health
    scan                       Trigger a WiFi scan
    list                       List available networks
    connect <SSID> [-p PASS]   Connect to a network
    disconnect                 Disconnect from current network
    forget <SSID>              Remove stored credentials
"""

import argparse
import sys

from . import DBUS_NAME, DBUS_PATH, DBUS_IFACE

try:
    import dbus
except ImportError:
    print(
        "Error: python3-dbus required.\n"
        "Install with: sudo dnf install python3-dbus",
        file=sys.stderr,
    )
    sys.exit(1)


def _get_iface():
    try:
        bus = dbus.SessionBus()
        obj = bus.get_object(DBUS_NAME, DBUS_PATH)
        return dbus.Interface(obj, DBUS_IFACE)
    except dbus.exceptions.DBusException as e:
        print(f"Cannot connect to bulwarkos-wifi daemon: {e}", file=sys.stderr)
        print(
            "Is the daemon running?\n"
            "  systemctl --user status bulwark-wifi-host",
            file=sys.stderr,
        )
        sys.exit(1)


def cmd_status(_args):
    iface = _get_iface()
    st    = dict(iface.Status())
    state = str(st.get("state", "unknown"))
    ssid  = str(st.get("ssid",  ""))
    proxy = bool(st.get("proxy_ok", False))

    print(f"sys-net connection:  {'OK' if proxy else 'UNAVAILABLE (sys-net running?)'}")
    print(f"WiFi state:          {state}")
    if ssid:
        print(f"Connected SSID:      {ssid}")


def cmd_scan(_args):
    iface = _get_iface()
    print("Scanning... (takes ~4 seconds)")
    if iface.Scan():
        print("Scan complete. Run 'bulwark-wifi list' to see results.")
    else:
        print("Scan failed — is sys-net running?", file=sys.stderr)
        sys.exit(1)


def cmd_list(_args):
    iface = _get_iface()
    nets  = iface.ListNetworks()
    if not nets:
        print("No networks found. Try 'bulwark-wifi scan' first.")
        return
    print(f"{'SSID':<35} {'SECURITY':<12} {'STRENGTH':>8}  STATUS")
    print("-" * 68)
    for n in nets:
        ssid     = str(n.get("ssid",     ""))
        security = str(n.get("security", "open"))
        strength = int(n.get("strength", -100))
        connected = n.get("connected", False)
        pct  = max(0, min(100, 2 * (strength + 100)))
        bars = "█" * (pct // 20) + "░" * (5 - pct // 20)
        flag = " [connected]" if connected else ""
        print(f"{ssid:<35} {security:<12} {strength:>5} dBm  {bars}{flag}")


def cmd_connect(args):
    iface = _get_iface()
    passphrase = getattr(args, "passphrase", "") or ""
    print(f"Connecting to '{args.ssid}'...")
    ok, msg = iface.Connect(args.ssid, passphrase)
    print(("OK: " if ok else "Failed: ") + msg)
    if not ok:
        sys.exit(1)


def cmd_disconnect(_args):
    iface = _get_iface()
    ok, msg = iface.Disconnect()
    print(("OK: " if ok else "Failed: ") + msg)
    if not ok:
        sys.exit(1)


def cmd_forget(args):
    iface = _get_iface()
    ok, msg = iface.Forget(args.ssid)
    print(("OK: " if ok else "Failed: ") + msg)
    if not ok:
        sys.exit(1)


def main():
    parser = argparse.ArgumentParser(
        prog="bulwark-wifi",
        description="Manage WiFi via sys-net",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=(
            "Examples:\n"
            "  bulwark-wifi status\n"
            "  bulwark-wifi scan && bulwark-wifi list\n"
            "  bulwark-wifi connect 'MyNetwork' --passphrase 'secret'\n"
            "  bulwark-wifi disconnect\n"
            "  bulwark-wifi forget 'MyNetwork'"
        ),
    )
    sub = parser.add_subparsers(dest="command", required=True)

    sub.add_parser("status",     help="Show connection status")
    sub.add_parser("scan",       help="Scan for available networks")
    sub.add_parser("list",       help="List scanned networks")

    p_conn = sub.add_parser("connect", help="Connect to a network")
    p_conn.add_argument("ssid")
    p_conn.add_argument(
        "--passphrase", "-p", default="",
        help="WPA/WPA2 passphrase (prompted if omitted for secured networks)"
    )

    sub.add_parser("disconnect", help="Disconnect from current network")

    p_forget = sub.add_parser("forget", help="Remove stored credentials")
    p_forget.add_argument("ssid")

    args = parser.parse_args()
    {
        "status":     cmd_status,
        "scan":       cmd_scan,
        "list":       cmd_list,
        "connect":    cmd_connect,
        "disconnect": cmd_disconnect,
        "forget":     cmd_forget,
    }[args.command](args)


if __name__ == "__main__":
    main()
